protocol.registerSchemesAsPrivileged([
    {
        scheme: 'play',
        privileges: {
            standard: true, 
            secure: true, 
            stream: true, 
            bypassCSP: true,
        },
    },
]);

protocol.handle('play', async (request) => {
        try {
            const u = new URL(request.url)
            const absPath = path.join(__dirname, u.hostname, u.pathname)
            let {start, end, isRange} = getRange(request.headers.get('Range'))
            const {size} = await promises.stat(absPath)
            if (end < 0) {
                end = size - 1
            }
            const chunkSize = (end || size - 1) - start + 1;
            const stream = fs.createReadStream(absPath, {start, end})
            stream.on('error', (error) => {
                try {
                    stream.destroy();
                } catch (e) {

                }
                return new Response(`Error: ${error.message}`, { status: 500 });
            });
            return new Response(stream, {
                status: isRange ? 206 : 200,
                headers: {
                    'Content-Range': `bytes ${start}-${end || size - 1}/${size}`,
                    'Accept-Ranges': 'bytes',
                    'Content-Length': chunkSize.toString(),
                    'Content-Type': mime.getType(absPath),
                }
            })
        } catch (e) {
            console.log(e, '22222')
        }

    })
```

